const webhookData = $("Forum Moderation Webhook").first().json.body || {};
const dbRows = $("Fetch Flagged Post & Author").all().map(i => i.json);

const postId = webhookData.post_id || (dbRows[0] && dbRows[0].id) || 'N/A';
const postTitle = (dbRows[0] && dbRows[0].title) || webhookData.title || 'Untitled Post';
const postContent = (dbRows[0] && dbRows[0].content) || webhookData.content || 'N/A';
const authorName = (dbRows[0] && dbRows[0].author_name) || webhookData.author_name || 'Anonymous';
const authorEmail = (dbRows[0] && dbRows[0].author_email) || webhookData.author_email || 'N/A';
const reason = webhookData.reason || 'Flagged for Review / Inappropriate Content';
const timestamp = new Date().toISOString();
const adminLink = 'http://localhost:3000/admin/forum';

const subject = `⚠️ [MODERATION ALERT] Flagged Forum Post #${postId}: "${postTitle}"`;
const body = `=====================================================\n⚠️ FORUM CONTENT MODERATION ALERT\n=====================================================\n\nFlagged Post Details:\n---------------------\n• Post ID:      ${postId}\n• Title:        ${postTitle}\n• Author:       ${authorName} (${authorEmail})\n• Flag Reason:  ${reason}\n• Timestamp:    ${timestamp}\n\nPost Content Snippet:\n---------------------\n"${postContent}"\n\nAction Required:\n----------------\nPlease review or remove this post in the Admin Panel:\n${adminLink}\n\n=====================================================\nSystem: Healthly Automated Moderation Service (n8n Workflow #3)\n`;

return [{
  json: {
    post_id: postId,
    post_title: postTitle,
    author_name: authorName,
    author_email: authorEmail,
    reason: reason,
    admin_link: adminLink,
    alert_subject: subject,
    alert_body: body,
    status: "MODERATION_ALERT_SENT"
  }
}];

